#include <deque>
using namespace std;

int main() {
    int n = 0;
    cin >> n;

    deque<int> d;
    for (int i = 0; i < n; i++) {
        int x = 0;
        cin >> x;
        d.push_front(x);
    }

    for (int x : d) {
        cout << x << endl;
    }
    cout << d.size() << endl;
    return 0;
}

